// ── CONFIGURABLE VARIABLES ──────────────────────────────────────
const GITHUB_OWNER  = 'YOUR_GITHUB_OWNER';   // e.g. 'microsoft'
const GITHUB_REPO   = 'YOUR_GITHUB_REPO';    // e.g. 'vscode'
const LANGUAGE      = 'EN';                  // 'EN' or 'FR'
const DAYS_BACK     = 7;
// ────────────────────────────────────────────────────────────────

const since = new Date(Date.now() - DAYS_BACK * 86400000).toISOString();
const until = new Date().toISOString();

return [{
  json: {
    owner:    GITHUB_OWNER,
    repo:     GITHUB_REPO,
    language: LANGUAGE,
    since,
    until
  }
}];

const config   = $('Set Config Variables').item.json;
const commits  = $('Fetch Commits').all().map(i => i.json);
const issues   = $('Fetch Closed Issues').all().map(i => i.json);
const allPRs   = $('Fetch Merged PRs').all().map(i => i.json);

// Filter only truly merged PRs and within the time window
const since = new Date(config.since);
const mergedPRs = allPRs.filter(pr =>
  pr.merged_at && new Date(pr.merged_at) >= since
);

// Filter issues that are not PRs
const closedIssues = issues.filter(i => !i.pull_request);

// Build compact summaries
const commitList = commits.slice(0, 30).map(c =>
  `- ${c.commit?.message?.split('\n')[0]} (@${c.author?.login || 'unknown'})`
).join('\n');

const issueList = closedIssues.slice(0, 20).map(i =>
  `- #${i.number}: ${i.title}`
).join('\n');

const prList = mergedPRs.slice(0, 20).map(p =>
  `- #${p.number}: ${p.title} (@${p.user?.login || 'unknown'})`
).join('\n');

const langInstruction = config.language === 'FR'
  ? 'Respond entirely in French.'
  : 'Respond entirely in English.';

const prompt = `You are a technical writer summarizing a GitHub repository's weekly activity.
${langInstruction}

Repository: ${config.owner}/${config.repo}
Period: ${config.since.slice(0,10)} → ${config.until.slice(0,10)}

## Commits (${commits.length} total, showing first 30)
${commitList || 'None'}

## Closed Issues (${closedIssues.length} total, showing first 20)
${issueList || 'None'}

## Merged Pull Requests (${mergedPRs.length} total, showing first 20)
${prList || 'None'}

Write a concise, engaging narrative summary (300–500 words) covering:
1. Major features or improvements shipped
2. Notable bug fixes or issues resolved
3. Key contributors this week
4. Overall health / momentum of the project

Use clear sections with Markdown headers. Be specific, reference PR/issue numbers where relevant.`;

return [{ json: { prompt, config, stats: { commits: commits.length, issues: closedIssues.length, prs: mergedPRs.length } } }];

const claudeResponse = $input.item.json;
const config  = $('Build Claude Prompt').item.json.config;
const stats   = $('Build Claude Prompt').item.json.stats;

const summary = claudeResponse.content?.[0]?.text || 'No summary generated.';

const dateLabel = new Date().toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' });
const repoLabel = `${config.owner}/${config.repo}`;

const discordPayload = {
  username: 'GitHub Weekly Bot',
  embeds: [
    {
      title: `📊 Weekly Summary — ${repoLabel}`,
      description: summary.slice(0, 4096),   // Discord embed limit
      color: 5814783,                         // purple
      footer: { text: `Week ending ${dateLabel} • ${stats.commits} commits • ${stats.issues} issues closed • ${stats.prs} PRs merged` }
    }
  ]
};

return [{ json: { summary, discordPayload, repoLabel, dateLabel } }];
